for (const button of document.querySelectorAll('.room-button')) {
  button.addEventListener('click', (event) => {
    document.querySelector('#selection').textContent = 'Current area: ' + event.target.dataset.roomCode;
  });
}

const draft = document.querySelector('#draft');
const output = document.querySelector('#literal');
draft.addEventListener('input', () => { output.innerHTML = draft.value || 'Waiting for input'; });

const pad = document.querySelector('#pad');
const button = document.querySelector('#tap');
const steps = [];
pad.addEventListener('click', () => steps.push('outer layer capture'));
button.addEventListener('click', () => steps.push('button'));
pad.addEventListener('click', () => {
  steps.push('outer layer bubbling');
  document.querySelector('#trace').textContent = steps.splice(0).join(' → ');
});

const serve = document.querySelector('#serve');
let count = 0;
function recordVisit() { document.querySelector('#served').textContent = ++count; }
serve.addEventListener('click', recordVisit);
document.querySelector('#stop').addEventListener('click', () => serve.removeEventListener('click', () => recordVisit()));

const form = document.querySelector('#application');
form.addEventListener('submit', (event) => {
  event.preventDefault();
  const data = new FormData(form);
  document.querySelector('#receipt').textContent = data.get('visitor').trim() + ':' + (data.get('session') || 'No sessions selected');
});

const password = document.querySelector('#password');
const confirm = document.querySelector('#confirm');
confirm.addEventListener('input', () => {
  const message = confirm.value && confirm.value !== password.value ? 'Two passwords are inconsistent' : '';
  confirm.setCustomValidity(message);
  document.querySelector('#feedback').textContent = message;
});

const devices = [{ name: 'rangefinder', code: 'L03' }, { name: 'angle ruler', code: 'R16' }];
const template = document.querySelector('#card-template');
document.querySelector('#build').addEventListener('click', () => {
  for (const device of devices) {
    const item = template.content.cloneNode(true);
    item.querySelector('.model').textContent = device.name;
    item.querySelector('.code').textContent = device.code;
    document.querySelector('#cards').append(item);
  }
});

const openButton = document.querySelector('#open');
const dialog = document.querySelector('#rules-dialog');
const dismiss = document.querySelector('#dismiss');
openButton.addEventListener('click', () => { dialog.show(); dismiss.focus(); });
dismiss.addEventListener('click', () => dialog.close());
dialog.addEventListener('close', () => openButton.focus());

const filter = document.querySelector('#filter');
let hits = 0;
filter.addEventListener('input', () => setTimeout(() => {
  document.querySelector('#last-keyword').textContent = filter.value;
  document.querySelector('#hits').textContent = ++hits;
}, 220));

const density = document.querySelector('#density');
density.textContent = localStorage.getItem('density') ?? 'standard';
document.querySelector('#reset-density').addEventListener('click', () => { localStorage.clear(); density.textContent = 'standard'; });
